<?php
namespace App\Services;
use App\Models\SalesDocumentHistory;
use Illuminate\Validation\ValidationException;
final class SalesDocumentService { private array $transitions=['quotation'=>['draft'=>['sent','rejected','expired'],'sent'=>['accepted','rejected','expired']],'order'=>['draft'=>['pending_approval','cancelled'],'pending_approval'=>['approved','rejected','cancelled'],'approved'=>['partially_fulfilled','fulfilled','cancelled'],'partially_fulfilled'=>['fulfilled','cancelled']],'delivery'=>['draft'=>['posted','cancelled']],'invoice'=>['draft'=>['issued','void'],'issued'=>['partially_paid','paid','void'],'partially_paid'=>['paid','void']],'payment'=>['pending_verification'=>['verified','rejected','reversed'],'verified'=>['reversed']]]; public function transition($document,string $type,string $to,?string $actorId=null,?string $comment=null):void { $from=$document->state; if(!in_array($to,$this->transitions[$type][$from]??[],true)) throw ValidationException::withMessages(['state'=>["Cannot transition {$type} from {$from} to {$to}."]]); $document->update(['state'=>$to]); SalesDocumentHistory::create(['tenant_id'=>$document->tenant_id,'document_type'=>$type,'document_id'=>$document->id,'actor_id'=>$actorId,'from_state'=>$from,'to_state'=>$to,'comment'=>$comment]); } }
